    fr_ent_5:"Corrige de espaldas, mientras recoge bolas.",
    fr_ent_6:"Entrena poco y bien. Odia las series eternas.",
    fr_ent_7:"Se sabe de memoria a los cincuenta primeros del ranking.",
    fr_ent_8:"Perdió una final por lo mismo que te pasa a ti.",
    fr_ent_9:"Nunca levanta la voz. Cuando la levanta, se para todo.",
    fr_ent_10:"Piensa en tres años vista. Tú, en el sábado.",
    fr_ent_11:"Le fascina el vídeo y aburre a todo el mundo con él.",
    fr_ent_12:"Su método es antiguo. Sus resultados no.",
    fr_fisio_5:"Sabe qué te duele antes de que lo digas.",
    fr_fisio_6:"Le da igual el calendario: si dice que no, es que no.",
    fr_fisio_7:"Viene de un equipo de baloncesto y se le nota.",
    fr_fisio_8:"Camilla a las siete de la mañana, sin excusas.",
    fr_fisio_9:"Habla poco y aprieta donde hay que apretar.",
    fr_fisio_10:"Tiene una libreta con todas tus molestias desde el primer día.",
    fr_fisio_11:"Ha recuperado a dos que daban por retirados.",
    fr_fisio_12:"Su frase favorita: «eso no es dolor, es información».",
