    fr_psico_6:"Trabaja el punto siguiente, nunca el anterior.",
    fr_psico_7:"Viene del atletismo, donde nadie te consuela.",
    fr_psico_8:"Escucha veinte minutos antes de decir una palabra.",
    fr_psico_9:"Odia la palabra «presión» y te la prohíbe.",
    fr_psico_10:"Te hace escribir tres líneas después de cada partido.",
    fr_psico_11:"Le da más importancia al sueño que a la charla.",
    fr_psico_12:"Estuvo en dos finales olímpicas. De otro deporte.",
    fr_fisico_5:"Cronómetro en mano y ni un segundo de más.",
    fr_fisico_6:"Cree en la fuerza. Toda su religión cabe ahí.",
    fr_fisico_7:"Te hace correr por la playa en enero.",
    fr_fisico_8:"Mide todo. Después te explica solo lo que importa.",
    fr_fisico_9:"Dice que el tercer set se gana en noviembre.",
    fr_fisico_10:"Antes preparaba ciclistas. Nunca lo olvida.",
    fr_fisico_11:"Es capaz de mandarte a casa a mitad de sesión.",
    fr_fisico_12:"No cree en el gimnasio de enero. Cree en el de agosto.",
    fr_rep_5:"Contesta el teléfono a las dos de la mañana.",
    fr_rep_6:"Nunca dice el precio primero. Nunca.",
