    fr_rep_8:"Se hizo agente porque no le llegó para jugador.",
    fr_rep_9:"Sabe qué marca va a entrar en el pádel antes que la marca.",
    fr_rep_10:"Cobra caro y no lo disimula.",
    fr_rep_11:"Ha roto contratos por una cláusula de dos líneas.",
    fr_rep_12:"Te dirá que no cuando tú quieras decir que sí.",
