    fr_ojeador_12:"Se equivocó una vez y todavía lo cuenta.",
    soc_vic_4:"Me he levantado a las seis para ver a {yo} y ha merecido la pena cada minuto ☕",
    soc_vic_5:"El 4-1 del segundo set. Ahí ha ganado {yo} el partido y nadie lo está diciendo.",
    soc_vic_6:"{rival} llevaba dos meses sin perder. Llevaba.",
    soc_vic_7:"Mi hija de nueve años quiere jugar como {yo}. Gracias por eso 🙏",
    soc_vic_8:"Sin hacer ruido, {yo} lleva tres semanas ganando a todo el mundo.",
    soc_vic_9:"Esa dejada del 5-4. La vuelvo a ver y sigo sin entenderla 🤯",
    soc_der_4:"Se pierde, se aprende y se vuelve. Lo de siempre con {yo}.",
    soc_der_5:"El problema no ha sido el partido, ha sido el calendario. Tres torneos seguidos no los aguanta nadie.",
    soc_der_6:"Cuando {yo} gana somos todos entrenadores. Hoy también, por lo visto 🙄",
    soc_der_7:"Dos horas y veinte. Ojalá todas las derrotas fueran así de dignas.",
    soc_der_8:"Contra {rival} en su casa y con su público. Hay derrotas que no cuentan.",
    soc_der_9:"Llevo siguiendo a {yo} desde el principio. Esto se pasa.",
    soc_tit_4:"Guardo esta foto para enseñársela a mis nietos. {TORNEO} 🏆",
    soc_tit_5:"Del último puesto del ranking a esto. Que alguien escriba la película.",
    soc_tit_6:"No me he movido del sofá en tres horas y no me arrepiento de nada 🏆",
    soc_tit_7:"Se lo merecía el equipo entero, no solo quien levanta la copa.",
    soc_tit_8:"Y todavía hay quien decía que {yo} no llegaría. Aquí lo dejo.",
    soc_fic_4:"Este movimiento cambia el circuito entero, no solo a {yo}.",
    soc_fic_5:"Lo llevaban semanas negociando y aquí nadie se enteró de nada 👀",
    soc_fic_6:"Sobre el papel encaja. En pista ya veremos.",
    soc_fic_7:"Ficha del año y estamos en marzo.",
    soc_fic_8:"A ver quién le explica ahora al de la pareja rota que esto es un deporte de amigos.",
    soc_pic_4:"Ha dicho lo que pensamos todos y encima con nombres 🌶",
    soc_pic_5:"Esa frase se va a leer en rueda de prensa durante un año.",
    soc_pic_6:"Sinceridad o marketing, no lo tengo claro. Funciona igual.",
    soc_pic_7:"El vestuario esta noche debe de ser un sitio incomodísimo 😬",
    soc_pic_8:"Menos mal que alguien habla. Llevábamos dos temporadas de entrevistas de cartón.",
    soc_les_3:"Fuerza {yo}. Las lesiones también son parte del oficio, por desgracia.",
    soc_les_4:"Se le veía cojear desde el primer juego y siguió. Eso también es competir.",
    soc_les_5:"Tres torneos en tres semanas y luego nos extrañamos.",
    soc_les_6:"Que se tome el tiempo que haga falta. Los puntos vuelven, las rodillas no.",
