    soc_for_5:"Cuidado con la sobrecarga. Lo digo por experiencia ajena.",
    soc_for_6:"Cinco partidos seguidos ganando el tercer set. Eso es cabeza, no piernas.",
    soc_jun_3:"La junta habla mucho y firma poco, como siempre.",
    soc_jun_4:"Si el objetivo era ese, que pongan el dinero para llegar.",
