    soc_gal_4:"Trajes, focos y cero pádel. Aun así, me lo he visto entero.",
    soc_gal_5:"Han premiado a quien tocaba y por una vez no hay discusión.",
    soc_gal_6:"Faltaba la mitad del vestuario. Eso también dice algo.",
    soc_riv_4:"{yo} contra {rival} es lo único que me hace poner el despertador.",
    soc_riv_5:"Ni se miran en el saludo. Esto lleva años cociéndose.",
