    tuto_sig:"Siguiente ›",
    tuto_ca_1_t:"Tu carrera",
    tuto_ca_1_x:"Tienes <b>16 años</b>, 2.500€ y el calendario real de 52 semanas. La semana va <b>de lunes a domingo</b>: el lunes te inscribes (o no), y cada día eliges entrenar o descansar. Si hay torneo, la previa cae martes-miércoles, los octavos el jueves... y la final, el domingo.",
    tuto_ca_2_t:"Dos circuitos",
    tuto_ca_2_x:"Cada semana hay un torneo <b>Continental</b> abierto y, muchas semanas, un <b>Élite</b> con corte por ranking. Si no llegas al corte de un Élite, puedes usar una de tus <b>2 wildcards</b> anuales para colarte en su previa.",
    tuto_ca_3_t:"Los torneos",
    tuto_ca_3_x:"Cada ronda se juega <b>en su día</b>. En los partidos que ves mandas tú: <b>táctica en vivo</b> (agresividad, buscar al flojo), <b>tiempo muerto</b> entre sets con tu charla, y <b>3 revisiones de vídeo</b>. Tras los partidos grandes, la prensa querrá titulares — mide tus palabras.",
    tuto_ca_4_t:"Tu pareja",
    tuto_ca_4_x:"Tu compañero tiene <b>química</b> (sube jugando juntos) y <b>moral</b>: si perdéis pronto y a menudo, se quema — y puede dejarte a final de temporada. En el mercado puedes fichar agentes libres o robar a jugadores del circuito.",
    tuto_ca_5_t:"El dinero",
    tuto_ca_5_x:"Premios reales (una Corona paga 60.000€ a la pareja campeona; un Continental Bronce, 800€), viajes que cuestan (Dubái no es Valladolid), patrocinios con objetivos y tu equipo: entrenador especialista a sueldo, fisio, psico, preparador y un <b>representante</b> que se lleva el 15%.",
    tuto_ca_6_t:"El mundo vive",
    tuto_ca_6_x:"Los puntos de cada torneo valen 52 semanas: cuando se cumple el año se caen, así que hay que defender lo que hiciste. Al cierre de temporada los veteranos se retiran, debutan jóvenes y hay rupturas de parejas. Objetivo: pisar el cuadro de un Élite... y algún día, el nº1. ¡Suerte!",
    tuto_cl_1_t:"Tu club",
    tuto_cl_1_x:"Eres el mánager de un club <b>masculino o femenino</b> (lo eliges al fundarlo): fichas jugadores de ese circuito y compites en su ranking. La plantilla (hasta 6) cobra salario semanal; socios y premios sostienen la caja.",
    tuto_cl_2_t:"Dos parejas",
    tuto_cl_2_x:"En Plantilla asignas la <b>pareja A</b> y la <b>pareja B</b>. La A juega su torneo contigo en el banquillo; la B puede ir a otro torneo en paralelo (resultado rápido, puntúa al 50% para el club).",
    tuto_cl_3_t:"El calendario",
    tuto_cl_3_x:"Continental abierto cada semana; Élite (Élite 2/Élite 1/Corona) con corte por ranking del club. La energía y las lesiones deciden a quién puedes alinear.",
    tuto_cl_4_t:"Entrenamiento",
    tuto_cl_4_x:"Cada jugador tiene su <b>plan</b> (golpe concreto o auto). Un botón entrena a toda la plantilla a la vez. Instalaciones, gimnasio y sala de vídeo mejoran el rendimiento.",
    tuto_cl_5_t:"Dinero y fichajes",
    tuto_cl_5_x:"Mercado de agentes libres (el ojeador trae joyas), academia con promesas, reformas del club, cuerpo técnico... y <b>clubes rivales</b> que fichan y vendrán con ofertas por los tuyos: tú decides si vendes.",
    tuto_cl_6_t:"El objetivo",
    tuto_cl_6_x:"La <b>junta</b> fija un objetivo de ranking cada temporada: cúmplelo y llega presupuesto extra; falla dos años seguidos y <b>te destituyen</b>. Ojo al mercado: los niveles ajenos son horquillas — el ojeador afina informes y huele el techo de cada promesa.",
