    ctx_sparring_n:"Hire a sparring partner",
    ctx_sparring_d:"Someone who makes you really play three hours a day, and not cheap.",
    ctx_sparring_e:"€420/week. You improve faster and your chemistry grows.",
    ctx_gimnasio_n:"Gym block",
    ctx_gimnasio_d:"Strength, ankles and back. The racket stays in the bag most of the week.",
    ctx_gimnasio_e:"€180/week. Less technique, far fewer injuries. Only improves baseline, wall, bandeja and smash.",
    ctx_video_n:"Video room",
    ctx_video_d:"Watching your rivals frame by frame until their pattern sticks.",
    ctx_video_e:"€130/week. Barely any attribute, but you compete with a cooler head.",
    ctx_stage_n:"Training camp",
    ctx_stage_d:"Ten days away doing nothing else. You come back a different player, if the body holds.",
    ctx_stage_e:"€1600/week and you do NOT compete that week. The biggest gain in the game, and the heaviest load.",
