    pj_charla_no:"Not the moment for this.",
    pj_sin_pareja:"With no partner there is no plan and nothing to talk about.",
    plan_libre_n:"No set plan",
    plan_libre_d:"Everyone plays their own game and improvises. Costs nothing, gives nothing.",
    plan_libre_c:"No automatisms to lose when you change partner.",
    plan_muro_n:"Block and counter",
    plan_muro_d:"Both at the back, one more ball, wait for the error. Ugly to watch, hard to break.",
    plan_muro_c:"Baseline and wall far more reliable, dangerous lob, weak smash.",
    plan_red_n:"Net domination",
    plan_red_d:"Always up, finish at the net. The point ends in three shots or they go over you.",
    plan_red_c:"Volley, bandeja and smash much stronger, but more errors.",
    plan_desgaste_n:"Bandeja and patience",
    plan_desgaste_d:"Bandeja after bandeja until they tire of never getting up. This is how third sets are won.",
    plan_desgaste_c:"Lethal, reliable bandeja, good lob, no smash and no rushing.",
    plan_reves_n:"Everything to the backhand",
    plan_reves_d:"Load relentlessly on the backhand-side player until their arm drops off.",
    plan_reves_c:"Víbora, chiquita and drop shot razor-sharp.",
    plan_escudo_n:"Protect your partner",
    plan_escudo_d:"You cover more court and they play fewer awkward balls. Almost no errors, and almost no winners.",
    plan_escudo_c:"Very few errors, but fewer winners too.",
    eje_deportiva_n:"On-court trust",
    eje_deportiva_d:"They believe in your game when the point burns.",
    eje_personal_n:"Personal bond",
    eje_personal_d:"Whether you get on off court or merely put up with each other.",
    eje_ambicion_n:"Shared ambition",
    eje_ambicion_d:"Whether you want the same from this season.",
    eje_protagonismo_n:"Sharing the spotlight",
    eje_protagonismo_d:"Who plays the balls that decide.",
    eje_lealtad_n:"Loyalty",
    eje_lealtad_d:"How long they hold out before listening to someone else.",
    eje_convivencia_n:"Living together",
    eje_convivencia_d:"Airports, hotels and dinners. It wears out.",
    chr_compromiso_n:"Ask for one more season",
    chr_compromiso_d:"Sit down and tell them you want to finish the year together, whatever happens.",
    chr_compromiso_e:"Raises ambition and loyalty. If they don't buy it, it lowers both.",
    chr_calendario_n:"Negotiate the calendar",
    chr_calendario_d:"Fewer tournaments, more days at home. You rest, but you compete less.",
    chr_calendario_e:"Recovers living-together at the cost of ambition.",
    chr_tactica_n:"Promise a tactical change",
    chr_tactica_d:"Admit the plan isn't working and commit to building another.",
    chr_tactica_e:"Raises on-court trust a lot. If it sounds like an excuse, it sinks it.",
    chr_critica_n:"Tell them what they're doing wrong",
    chr_critica_d:"The uncomfortable one: you've watched the same mistake for three weeks.",
    chr_critica_e:"Can fix their game or cost you the relationship. Nearly half go wrong.",
    chr_defender_n:"Back them in public",
    chr_defender_d:"The press is blaming them for the defeat. You go out and take it.",
    chr_defender_e:"Almost never backfires: raises bond and loyalty.",
    chr_psicologo_n:"Pay for a psychologist",
    chr_psicologo_d:"Not your problem, and it costs money. But they haven't slept well in six months.",
    chr_psicologo_e:"€900. Raises bond, trust and living-together.",
    chr_bolas_n:"Give them the decisive balls",
    chr_bolas_d:"Tell them that at 5-5 they take it. And mean it.",
    chr_bolas_e:"Raises spotlight-sharing a lot, at the cost of your weight on court.",
    chr_salida_n:"Prepare a way out",
    chr_salida_d:"This is over and you both know it. Whether it ends well depends on this conversation.",
    chr_salida_e:"Raises loyalty and bond: you split without burning bridges.",
