    ev_humedad_n:"Heavy court",
    ev_humedad_x:"The damp has left the court slow and the ball dies on the glass. You don't finish points with one shot here.",
    ev_humedad_e:"Lob and baseline rule; smash and víbora lose their edge.",
    ev_vuelo_n:"Missed flight",
    ev_vuelo_x:"Airport strike. You arrive late, short of sleep and paying triple for the ticket.",
    ev_vuelo_e:"Travel costs double and you arrive 16 energy down.",
    ev_gripe_n:"Flu",
    ev_gripe_x:"Thirty-eight degrees on Tuesday. Nothing serious, but the body won't answer and pushing it has a price.",
    ev_gripe_e:"Energy is capped at 58 and injury risk is up 40%.",
    ev_compi_tocado_n:"Your partner is off",
    ev_compi_tocado_x:"He woke up with a tight back and won't say so. You can see it at the net: half a step late to everything.",
    ev_compi_tocado_e:"Chemistry drops 22 points and the volley loses bite.",
    ev_suplente_n:"Forced stand-in",
    ev_suplente_x:"Your partner can't make the tournament. Either you play with whoever's on the waiting list, or you stay home.",
    ev_suplente_e:"This tournament you play with a weaker stand-in and no chemistry.",
    ev_hostil_n:"Hostile crowd",
    ev_hostil_x:"Something you said in March. The stands haven't forgotten, and this week they'll remind you every point.",
    ev_hostil_e:"Confidence is capped at 52, but winning here is worth double the followers.",
    ev_pelota_n:"New ball",
    ev_pelota_x:"The tournament has a new supplier. The ball flies faster and bounces high: points end sooner and touch shots go astray.",
    ev_pelota_e:"Smash and víbora gain; lob and drop shot turn treacherous.",
    ev_altitud_n:"Altitude tournament",
    ev_altitud_x:"Two thousand metres. The ball weighs nothing, points last three shots, and whoever breathes better rules.",
    ev_altitud_e:"Everyone wins more balls and misses more: a coin-toss of a match.",
    ev_crisis_n:"Crisis of confidence",
    ev_crisis_x:"Five defeats in a row. It isn't the game any more: you walk on court expecting it to go wrong.",
    ev_crisis_e:"For four weeks confidence is capped at 46.",
    ev_comprimido_n:"Compressed calendar",
    ev_comprimido_x:"Three tournaments in three weeks and two continents. Somebody drew the calendar with the wrong map.",
    ev_comprimido_e:"You recover 7 less energy a week for three weeks.",
    ev_gira_n:"International swing",
    ev_gira_x:"Five weeks away: Doha, Mexico City, Buenos Aires. Travel is expensive and you play in front of big crowds.",
    ev_gira_e:"Travel costs 80% more, but tournaments award 15% more points.",
    ev_impago_n:"Sponsor withholds payment",
    ev_impago_x:"An image clause nobody read. Until it's sorted, the contract money doesn't arrive.",
    ev_impago_e:"Four weeks with no sponsor income.",
    ev_punto_oro_n:"Golden point mandatory",
    ev_punto_oro_x:"The tour scraps advantages this season: 40-40 is decided by one point. Matches get shorter and the favourite is less of one.",
    ev_punto_oro_e:"The whole season on golden point: far more variance in every game.",
    ev_puntos_nuevos_n:"New points system",
    ev_puntos_nuevos_x:"The federation hands out more points to shake up the ranking. A good year is worth double now; a bad one costs double too.",
    ev_puntos_nuevos_e:"Every tournament awards 30% more points this season.",
    ev_calendario_corto_n:"Reduced calendar",
    ev_calendario_corto_x:"Tournaments cut back for the tour's overhaul. Fewer weeks to score and the same to defend.",
    ev_calendario_corto_e:"Some weeks have no Continental event: choosing when to play matters more.",
    ev_generacion_n:"A once-in-a-lifetime generation",
    ev_generacion_x:"Four pairs under twenty arrive at once and none of them looks like a debut. The tour just went up a level.",
    ev_generacion_e:"Four young pairs at level 70-78 join the tour.",
    ev_caida_dominio_n:"A reign ends",
    ev_caida_dominio_x:"The pair that ruled for years has stopped being the pair that ruled for years. You see it in their faces before the scoreboard.",
    ev_caida_dominio_e:"The world number one loses level: the draw opens up at the top.",
    ev_sorteo_nemesis_n:"The draw shows no mercy",
    ev_sorteo_nemesis_x:"Of all the pairs in the draw, you got the one you have unfinished business with. First round.",
    ev_sorteo_nemesis_e:"Your first opponent at the next tournament is your nemesis.",
    ev_ex_provoca_n:"Your ex-partner talks",
    ev_ex_provoca_x:"A long interview and two lines too many. One of them was about why you stopped playing together.",
    ev_ex_provoca_e:"The locker room sours: your partner's chemistry and morale drop.",
    ev_entrenador_revela_n:"Your old coach talks",
    ev_entrenador_revela_x:"He works with other people now, and told a podcast how you read the big points. Half the tour has heard it.",
    ev_entrenador_revela_e:"For a month opponents read you: every shot loses 7%.",
