    cfil_hd:"Club philosophy",
    cfil_ayuda:"It sets who you can convince and who you can't. A player who doesn't fit asks for more money, and one who fits not at all won't sign.",
    cfil_cantera_n:"Home-grown",
    cfil_cantera_d:"Here you come up from below. Youngsters sign cheap and eager; veterans need money to be convinced.",
    cfil_cantera_l:"From the academy to the first team",
