    cfil_estrellas_d:"You sign the finished article. Quality players want in; long-term projects go elsewhere.",
    cfil_estrellas_l:"You come here to win now",
    cfil_garra_n:"Blood and guts",
    cfil_garra_d:"Every ball gets chased. Fighters and emotional players sign for less; comfortable ones can't stand the idea.",
    cfil_garra_l:"We run to the last point",
    cfil_oficio_n:"The school",
    cfil_oficio_d:"You play with your head. Builders and cool heads fit naturally; pure finishers ask for a premium.",
