    dil_beca_t:"Free gear, with small print",
    dil_beca_x:"A local brand offers you rackets and kit for the whole season. In exchange, exclusivity: not one photo with another brand. They pay little, but they pay now.",
    dil_beca_o1:"Sign",
    dil_beca_o1d:"Money now, hands tied later.",
    dil_beca_o1c:"The exclusivity keeps you out of a big campaign.",
    dil_beca_o2:"Say thanks and move on",
    dil_beca_o2d:"You'll struggle, but free.",
    dil_prensa_t:"The microphone after a loss",
    dil_prensa_x:"A reporter is waiting outside the locker room. He wants you to say the tour's level has collapsed. You've just lost and you're fuming.",
    dil_prensa_o1:"Let it all out",
    dil_prensa_o1d:"The headline is yours. So are the consequences.",
    dil_prensa_o1c:"Half the locker room stops greeting you.",
    dil_prensa_o2:"Two polite sentences",
    dil_prensa_o2d:"Boring, but nobody clips the quote.",
    dil_clinic_t:"A morning with the kids",
    dil_clinic_x:"The club where you started asks you for a clinic for its juniors. They pay nothing. Eighty kids will come, and their parents, all with phones in hand.",
    dil_clinic_o1:"Go, and stay to the end",
    dil_clinic_o1d:"It's tiring. And it's remembered.",
    dil_clinic_o1c:"The club sends you an envelope you weren't expecting.",
    dil_clinic_o2:"Not this time",
    dil_clinic_o2d:"You rest. Someone will remember.",
    dil_dop_t:"Testers at seven in the morning",
    dil_dop_x:"Two anti-doping officers ring the bell. It's a surprise, it's legal and it's today. You had training in two hours and it was a short night.",
    dil_dop_o1:"Open up and cooperate",
    dil_dop_o1d:"Two hours gone, then training.",
    dil_dop_o2:"Tell them to come back later",
    dil_dop_o2d:"Nothing good comes of this.",
    dil_dop_o2c:"Refusing counts as a positive. Fine and headlines.",
    dil_pala_t:"{marca}'s new racket",
    dil_pala_x:"{marca} is launching a new model and wants it in your hands this weekend. You've had the old one for two years and you know it like your own hand.",
    dil_pala_o1:"Debut it on Saturday",
    dil_pala_o1d:"You get paid for the exclusive. And play blind.",
    dil_pala_o1c:"It takes weeks to find its sweet spot.",
    dil_pala_o2:"Stick with the old one",
    dil_pala_o2d:"Your game first.",
    dil_pala_o2c:"The brand isn't amused and trims your retainer.",
