    dil_prensa_o2d:"Langweilig, aber niemand schneidet das Zitat mit.",
    dil_clinic_t:"Ein Vormittag mit den Kindern",
    dil_clinic_x:"Der Club, in dem du angefangen hast, bittet dich um ein Camp für seine Jugend. Sie zahlen nichts. Achtzig Kinder kommen, dazu die Eltern, alle mit dem Handy in der Hand.",
    dil_clinic_o1:"Hingehen und bis zum Schluss bleiben",
    dil_clinic_o1d:"Es ermüdet. Und es bleibt in Erinnerung.",
    dil_clinic_o1c:"Der Club schickt dir einen Umschlag, mit dem du nicht gerechnet hast.",
    dil_clinic_o2:"Diesmal nicht",
    dil_clinic_o2d:"Du ruhst dich aus. Jemand wird sich erinnern.",
    dil_dop_t:"Kontrolle um sieben Uhr morgens",
    dil_dop_x:"Zwei Dopingkontrolleure klingeln. Unangekündigt, rechtens und heute. In zwei Stunden war Training und die Nacht war kurz.",
    dil_dop_o1:"Öffnen und mitmachen",
    dil_dop_o1d:"Zwei Stunden weg, dann Training.",
    dil_dop_o2:"Sagen, sie sollen später kommen",
    dil_dop_o2d:"Daraus wird nichts Gutes.",
    dil_dop_o2c:"Verweigerung gilt als positiv. Geldstrafe und Schlagzeilen.",
    dil_pala_t:"Der neue Schläger von {marca}",
    dil_pala_x:"{marca} bringt ein neues Modell heraus und will es dieses Wochenende in deinen Händen sehen. Du spielst seit zwei Jahren mit dem alten und kennst ihn wie deine Hand.",
    dil_pala_o1:"Am Samstag einweihen",
    dil_pala_o1d:"Du kassierst für die Exklusivität. Und spielst blind.",
    dil_pala_o1c:"Du brauchst Wochen, bis er sitzt.",
    dil_pala_o2:"Beim alten bleiben",
    dil_pala_o2d:"Dein Spiel zuerst.",
    dil_pala_o2c:"Die Marke findet das nicht witzig und kürzt das Fixum.",
    dil_fam_t:"Die Hochzeit deiner Schwester",
    dil_fam_x:"Sie heiratet am Samstag. Am Samstag ist Halbfinale. Seit einem Jahr sagt sie dir das Datum, und seit einem Jahr sagst du, mal sehen.",
    dil_fam_o1:"Zur Hochzeit gehen",
    dil_fam_o1d:"Du erholst dich wirklich, ausnahmsweise.",
    dil_fam_o1c:"Der Rückzug aus dem Feld kostet mehr als gedacht.",
    dil_fam_o2:"Spielen und abends anrufen",
    dil_fam_o2d:"Sie versteht es. Sagt sie.",
    dil_inv_t:"Geld heute gegen Geld morgen",
    dil_inv_x:"Ein Investor streckt dir jetzt neuntausend Euro vor, gegen einen Anteil an deinen Preisgeldern für anderthalb Jahre. Damit könntest du überall hinreisen.",
    dil_inv_o1:"Den Vorschuss nehmen",
    dil_inv_o1d:"Geld, um überall hinzureisen, sofort.",
    dil_inv_o1c:"Die Abrechnung kommt und tut mehr weh als gedacht.",
    dil_inv_o2:"Im eigenen Tempo bleiben",
    dil_inv_o2d:"Langsamer, aber deins.",
    dil_viral_t:"Das Video, das du nicht wolltest",
    dil_viral_x:"Jemand hat deinen Streit mit dem Schiedsrichter gefilmt, das Video hat eine halbe Million Aufrufe. Die einen lachen, die anderen fordern eine Strafe.",
    dil_viral_o1:"Mitspielen",
    dil_viral_o1d:"Die Figur verkauft sich. Vorerst.",
    dil_viral_o1c:"Der Verband eröffnet ein Verfahren und verhängt eine Geldstrafe.",
    dil_viral_o2:"Sich entschuldigen, fertig",
    dil_viral_o2d:"Du verlierst Anhänger. Du gewinnst die Kabine.",
    dil_tec_t:"Jemand will {n}",
    dil_tec_x:"Ein Top-10-Rivale hat {n} das Doppelte von dem geboten, was du zahlst. Er sagt es dir selbst, aus Ehrlichkeit. Er wartet auf eine Antwort.",
    dil_tec_o1:"Das Angebot mitgehen",
    dil_tec_o1d:"Teuer. Sehr. Aber er bleibt.",
    dil_tec_o1c:"Er bleibt, und man merkt es: das Team zieht mit.",
    dil_tec_o2:"Ihm Glück wünschen",
    dil_tec_o2d:"Mit dem Gehalt kannst du nicht mithalten.",
    dil_cle_t:"{n} will spielen",
    dil_cle_x:"{n} schleppt seit Dienstag eine Blessur mit sich und der Physio hat abgeraten. Aber es ist das Finale, und er schaut dich an und wartet auf ein Ja.",
    dil_cle_o1:"Spielen lassen",
    dil_cle_o1d:"Du vertraust ihm. Er merkt es.",
    dil_cle_o1c:"Es reißt ganz, und er macht dir stumme Vorwürfe.",
    dil_cle_o2:"Vom Finale zurückziehen",
    dil_cle_o2d:"Die vernünftige Wahl. Und die schmerzhafteste.",
    dil_ej_t:"Spielen und trainieren zugleich",
    dil_ej_x:"Ein Club bietet dir eine Spielertrainer-Rolle: Festgehalt fürs Spielen und dazu die Jugend an drei Nachmittagen pro Woche.",
    dil_ej_o1:"Die Stelle annehmen",
    dil_ej_o1d:"Zum ersten Mal im Leben ein festes Gehalt.",
    dil_ej_o1c:"Die Nachmittage mit der Jugend lassen dich ohne Beine zurück.",
    dil_ej_o2:"Ich bin noch Spieler",
    dil_ej_o2d:"Zum Lehren bleibt später Zeit.",
    dil_can_t:"Zwei Angebote für denselben Samstag",
    dil_can_x:"Dein alter Club feiert sein fünfzigjähriges Bestehen und will dich dabeihaben. Am selben Tag zahlt ein Einkaufszentrum für eine Autogrammstunde.",
    dil_can_o1:"Zum alten Club",
    dil_can_o1d:"Sie zahlen nicht. Sie erinnern sich.",
    dil_can_o2:"Zur Autogrammstunde",
    dil_can_o2d:"Zahlt gut und dauert zwei Stunden.",
    dil_can_o2c:"In deinem Club sagt es keiner, aber man merkt es.",
