    patro_perfil_fijo:"hohes Fixum",
    patro_perfil_obj:"leistungsbasiert",
    tuto_paso:"SCHRITT {i} / {n}",
    tuto_fin:"Auf geht's!",
    tuto_sig:"Weiter ›",
    tuto_ca_1_t:"Deine Karriere",
    tuto_ca_1_x:"Du bist <b>16 Jahre alt</b>, hast 2.500€ und den echten 52-Wochen-Kalender. Die Woche läuft <b>von Montag bis Sonntag</b>: Montags meldest du dich an (oder nicht), und jeden Tag wählst du zwischen Training und Erholung. Gibt es ein Turnier, fällt die Quali auf Dienstag-Mittwoch, das Achtelfinale auf Donnerstag... und das Finale auf Sonntag.",
    tuto_ca_2_t:"Zwei Circuits",
    tuto_ca_2_x:"Jede Woche gibt es ein offenes <b>Continental</b>-Turnier und oft ein <b>Elite</b> mit Ranking-Cut. Verpasst du den Cut eines Elite, kannst du eine deiner <b>2 Wildcards</b> pro Jahr nutzen, um dich in die Quali zu schmuggeln.",
    tuto_ca_3_t:"Die Turniere",
    tuto_ca_3_x:"Jede Runde wird <b>an ihrem Tag</b> gespielt. In Matches, die du anschaust, hast du das Sagen: <b>Live-Taktik</b> (Aggressivität, den Schwachen anspielen), <b>Auszeit</b> zwischen den Sätzen mit deiner Ansprache und <b>3 Videobeweise</b>. Nach großen Matches will die Presse Schlagzeilen — wäge deine Worte ab.",
    tuto_ca_4_t:"Dein Partner",
    tuto_ca_4_x:"Dein Partner hat <b>Chemie</b> (wächst durch gemeinsames Spielen) und <b>Moral</b>: Verliert ihr früh und oft, brennt er aus — und kann dich am Saisonende verlassen. Auf dem Markt kannst du vereinslose Spieler holen oder Spieler vom Circuit abwerben.",
    tuto_ca_5_t:"Das Geld",
    tuto_ca_5_x:"Echte Preisgelder (eine Krone zahlt dem Siegerpaar 60.000€; ein Continental Bronze 800€), Reisen, die kosten (Dubai ist nicht Valladolid), Sponsoren mit Zielen und dein Team: Spezialtrainer auf Gehalt, Physio, Psychologe, Fitnesstrainer und ein <b>Agent</b>, der 15% nimmt.",
    tuto_ca_6_t:"Die Welt lebt",
    tuto_ca_6_x:"Die Punkte eines Turniers gelten 52 Wochen: nach einem Jahr fallen sie weg, du musst also verteidigen, was du geholt hast. Zum Saisonende treten Routiniers ab, Junge debütieren und Paare trennen sich. Ziel: das Hauptfeld eines Élite erreichen … und eines Tages die Nummer 1. Viel Glück!",
    tuto_cl_1_t:"Dein Club",
    tuto_cl_1_x:"Du bist Manager eines <b>Männer- oder Frauen</b>clubs (du wählst bei der Gründung): Du verpflichtest Spieler dieses Circuits und spielst um sein Ranking. Der Kader (bis zu 6) bezieht Wochenlohn; Mitglieder und Preisgelder tragen die Kasse.",
    tuto_cl_2_t:"Zwei Paare",
    tuto_cl_2_x:"Im Kader bestimmst du <b>Paar A</b> und <b>Paar B</b>. A spielt sein Turnier mit dir auf der Bank; B kann parallel zu einem anderen Turnier (schnelles Ergebnis, zählt 50% für den Club).",
    tuto_cl_3_t:"Der Kalender",
    tuto_cl_3_x:"Offenes Continental jede Woche; Elite (Elite 2/Elite 1/Krone) mit Cut nach Club-Ranking. Energie und Verletzungen entscheiden, wen du aufstellen kannst.",
    tuto_cl_4_t:"Training",
    tuto_cl_4_x:"Jeder Spieler hat seinen <b>Plan</b> (konkreter Schlag oder Auto). Ein Knopf trainiert den ganzen Kader auf einmal. Anlagen, Gym und Videoraum steigern die Leistung.",
    tuto_cl_5_t:"Geld und Transfers",
    tuto_cl_5_x:"Markt für Vereinslose (der Scout bringt Juwelen), Akademie mit Talenten, Umbauten, Trainerstab... und <b>Rivalen-Clubs</b>, die einkaufen und mit Angeboten für deine Spieler kommen: Du entscheidest, ob du verkaufst.",
    tuto_cl_6_t:"Das Ziel",
    tuto_cl_6_x:"Der <b>Vorstand</b> setzt jede Saison ein Ranking-Ziel: Erreich es und Extra-Budget kommt; scheitere zwei Jahre in Folge und <b>du wirst entlassen</b>. Vorsicht am Markt: fremde Niveaus sind Spannen — der Scout schärft Berichte und wittert das Potenzial jedes Talents.",
