    soc_vic_1:"Che livello oggi di {yo} 🔥 {rival} non sapeva dove mettersi",
    soc_vic_2:"Che partita ho appena visto. {yo} fa sul serio 👏",
    soc_vic_3:"Quello che è successo a {torneo} va incorniciato. FORZA {YO}",
    soc_der_1:"Botta dura oggi... ma se ne esce. Fiducia cieca in {yo} 💪",
    soc_der_2:"Qualcuno mi spiega cos'è successo a {torneo} perché non ci credo",
    soc_der_3:"Una giornata storta capita a tutti. Lunedì si riparte, {yo} ❤",
    soc_tit_1:"CAMPIONI 🏆🏆🏆 {YO} È UN'ALTRA COSA",
    soc_tit_2:"Mi è scesa una lacrimuccia con questo titolo, non vi mento 🥹",
    soc_tit_3:"{TORNEO} A CASA. CHE MOMENTO",
    soc_fic_1:"Occhio al movimento 👀 mi piace MOLTO per {yo}",
    soc_fic_2:"Bomba di mercato!! questo cambia la stagione",
    soc_fic_3:"Non so se è l'acquisto che serviva ma l'entusiasmo c'è 🤞",
    soc_pic_1:"AHAHAH le dichiarazioni di oggi 🌶 così si parla",
    soc_pic_2:"Si scatenerà un putiferio dopo quelle dichiarazioni... e mi piace",
    soc_pic_3:"Meno titoli e più campo, dico io 🤷",
    soc_les_1:"No no no non l'infortunio 😭 rimettiti presto",
