    tuto_paso:"PASSO {i} / {n}",
    tuto_fin:"Si gioca!",
    tuto_sig:"Avanti ›",
    tuto_ca_1_t:"La tua carriera",
    tuto_ca_1_x:"Hai <b>16 anni</b>, 2.500€ e il vero calendario di 52 settimane. La settimana va <b>da lunedì a domenica</b>: il lunedì ti iscrivi (o no), e ogni giorno scegli se allenarti o riposare. Se c'è un torneo, le qualificazioni cadono martedì-mercoledì, gli ottavi il giovedì... e la finale, la domenica.",
    tuto_ca_2_t:"Due circuiti",
    tuto_ca_2_x:"Ogni settimana c'è un torneo <b>Continental</b> aperto e, spesso, un <b>Élite</b> con taglio per classifica. Se non rientri nel taglio di un Élite, puoi usare una delle tue <b>2 wildcard</b> annuali per infilarti nelle sue qualificazioni.",
    tuto_ca_3_t:"I tornei",
    tuto_ca_3_x:"Ogni turno si gioca <b>nel suo giorno</b>. Nelle partite che guardi comandi tu: <b>tattica dal vivo</b> (aggressività, puntare il debole), <b>timeout</b> tra i set col tuo discorso e <b>3 revisioni video</b>. Dopo le grandi partite la stampa vorrà titoli — pesa le parole.",
    tuto_ca_4_t:"Il tuo partner",
    tuto_ca_4_x:"Il tuo compagno ha <b>chimica</b> (cresce giocando insieme) e <b>morale</b>: se perdete presto e spesso si logora — e può lasciarti a fine stagione. Sul mercato puoi ingaggiare svincolati o soffiare giocatori al circuito.",
    tuto_ca_5_t:"I soldi",
    tuto_ca_5_x:"Premi reali (una Corona paga 60.000€ alla coppia campione; un Continental Bronzo, 800€), viaggi che costano (Dubai non è Valladolid), sponsor con obiettivi e la tua squadra: allenatore specialista a stipendio, fisio, psicologo, preparatore e un <b>agente</b> che si prende il 15%.",
    tuto_ca_6_t:"Il mondo vive",
    tuto_ca_6_x:"I punti di ogni torneo valgono 52 settimane: allo scadere dell'anno cadono, quindi bisogna difendere quel che hai fatto. A fine stagione i veterani si ritirano, debuttano giovani e le coppie si rompono. Obiettivo: entrare nel tabellone di un Élite... e un giorno, il nº1. Buona fortuna!",
    tuto_cl_1_t:"Il tuo club",
    tuto_cl_1_x:"Sei il manager di un club <b>maschile o femminile</b> (lo scegli alla fondazione): ingaggi giocatori di quel circuito e competi nella sua classifica. La rosa (fino a 6) prende uno stipendio settimanale; soci e premi sostengono la cassa.",
    tuto_cl_2_t:"Due coppie",
    tuto_cl_2_x:"In Rosa assegni la <b>coppia A</b> e la <b>coppia B</b>. La A gioca il suo torneo con te in panchina; la B può andare a un altro torneo in parallelo (risultato rapido, vale il 50% per il club).",
    tuto_cl_3_t:"Il calendario",
    tuto_cl_3_x:"Continental aperto ogni settimana; Élite (Élite 2/Élite 1/Corona) con taglio per classifica del club. Energia e infortuni decidono chi puoi schierare.",
    tuto_cl_4_t:"Allenamento",
    tuto_cl_4_x:"Ogni giocatore ha il suo <b>piano</b> (colpo specifico o auto). Un pulsante allena tutta la rosa in una volta. Strutture, palestra e sala video migliorano il rendimento.",
    tuto_cl_5_t:"Soldi e mercato",
    tuto_cl_5_x:"Mercato degli svincolati (l'osservatore porta gioielli), accademia con promesse, lavori al club, staff tecnico... e <b>club rivali</b> che comprano e arriveranno con offerte per i tuoi: decidi tu se vendere.",
    tuto_cl_6_t:"L'obiettivo",
    tuto_cl_6_x:"Il <b>consiglio</b> fissa un obiettivo di classifica ogni stagione: centralo e arriva budget extra; fallisci due anni di fila e <b>ti esonerano</b>. Occhio al mercato: i livelli altrui sono forchette — l'osservatore affina i rapporti e fiuta il tetto di ogni promessa.",
