function idiomaValido(id){ return IDIOMAS.some(l=>l.id===id); }
// Idioma vigente: la preferencia guardada en el menú, o el español por defecto.
function idiomaActual(){ try{ const s=localStorage.getItem("rpm_idioma"); if(idiomaValido(s)) return s; }catch(e){} return IDIOMA_DEF; }
// Traduce una clave al idioma vigente, con doble red: idioma por defecto y, si
// tampoco existe, la propia clave (así una clave sin traducir se nota, no rompe).
// Con un segundo argumento, interpola: los marcadores {campo} de la cadena se
// sustituyen por params[campo]. Así los mensajes con datos (nombres, cifras) se
// traducen sin romper el orden de las palabras entre idiomas.
function t(clave,params){
  const L=I18N[idiomaActual()]||I18N[IDIOMA_DEF], D=I18N[IDIOMA_DEF];
  let s = (L&&L[clave]!=null) ? L[clave] : ((D&&D[clave]!=null)?D[clave]:clave);
  if(params&&typeof s==="string"&&s.indexOf("{")>=0){
    s=s.replace(/\{(\w+)\}/g,(m,k)=> (params[k]!=null?params[k]:m));
  }
  return s;
}
// Nombre y descripción de una dificultad en el idioma vigente.
function difNombre(id){ return t("dif_"+(id||DIF_DEF)+"_n"); }
function difDesc(id){ return t("dif_"+(id||DIF_DEF)+"_desc"); }
const _DIAS_I18N=["dia_lunes","dia_martes","dia_miercoles","dia_jueves","dia_viernes","dia_sabado","dia_domingo"];
// Nombre del día (0=lunes) en el idioma vigente.
function diaNombre(i){ return t(_DIAS_I18N[((i%7)+7)%7]); }
// Nombre y descripción de estilos y personalidades en el idioma vigente.
function estiloNombre(k){ return t("estilo_"+k+"_n"); }
function estiloDesc(k){ return t("estilo_"+k+"_d"); }
function persoNombre(k){ return t("perso_"+k+"_n"); }
function persoDesc(k){ return t("perso_"+k+"_d"); }
// Nombre de la fase de torneo (0..5) en el idioma vigente.
function faseNombre(i){ return t("fase_"+i); }
// Tier de patrocinio (1..4) en el idioma vigente.
function tierTxt(n){ return t("tier_"+n); }
// Nombre de una lesión en el idioma activo. Acepta el objeto lesión ({k,n}) o
// un string; las lesiones de partidas antiguas (sin clave k) conservan su texto.
function lesNombre(l){ if(!l) return ""; if(typeof l==="string") return l; return l.k?t(l.k):(l.n||""); }
// Nombre visible de un golpe/atributo (fondo, globo, víbora...). La CLAVE interna
// nunca cambia: solo se traduce al pintarla.
function atNombre(k){ return t("at_"+k); }
function atLista(ks){ return (ks||[]).map(atNombre); }

// Aplica el idioma vigente al texto estático de la interfaz: recorre los
// elementos marcados con data-i18n (contenido) y data-i18n-title (tooltip) y los
// traduce. Es el mecanismo para ir internacionalizando el juego por fases: basta
// con marcar más elementos en el HTML y añadir sus claves, sin tocar lógica.
function aplicarI18n(root){
  try{
    const doc=(root&&root.querySelectorAll)?root:(typeof document!=="undefined"?document:null);
    if(!doc) return;
    doc.querySelectorAll("[data-i18n]").forEach(el=>{ el.textContent=t(el.getAttribute("data-i18n")); });
    // data-i18n-html: para textos con formato (un <em> de estilo dentro), donde la
    // traducción incluye el propio marcado. Las cadenas provienen solo de i18n.js.
    doc.querySelectorAll("[data-i18n-html]").forEach(el=>{ el.innerHTML=t(el.getAttribute("data-i18n-html")); });
    doc.querySelectorAll("[data-i18n-title]").forEach(el=>{ el.setAttribute("title",t(el.getAttribute("data-i18n-title"))); });
  }catch(e){}
}
